#!/usr/bin/env bash
# ============================================================================
# EWA batch4-ewa — ARBITRATION (VerifyJury + ThreatMarket)
# FIXED 2026-10-02: jury params from tests; ThreatMarket wired to this batch's jury.
#
# RUN (Termux):
#   cd ~/eva-contracts && git pull   # needs batch1 first (INCIDENTREG)
#   export PK=0x...                 # founder signer key (never paste in chat)
#   export CONFIRM_DEFAULTS=yes     # ONLY after reviewing the defaults below
#   bash deployments/batch4-ewa.sh
#   unset PK && history -c
# ============================================================================
set -euo pipefail

RPC="${RPC:-https://mainnet.base.org}"
EWA_CORE=0x0201981D7BFE0E79DEACb0B5eae0F83022Cc18eB
FOUNDER=0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8
: "${PK:?export PK=0x... first}"
: "${INCIDENTREG:?need INCIDENTREG from batch1 (run batch1 first)}"

echo "=================================================================="
echo "EWA batch4-ewa — ARBITRATION"
echo "Founder: REVIEW these defaults/params before proceeding:"
echo "  jury: registry=INCIDENTREG(batch1) window=3d minVoters=3 maxVoters=50 whaleCap=2000bp reporter=500bp minStake=1 EWA [from tests]"
echo "  threat: jury=$VERIFYJURY(this batch) juryStakeBp=20000(2x) [from tests]"
echo "=================================================================="
if [ "${CONFIRM_DEFAULTS:-}" != "yes" ]; then
  echo "ABORT: set CONFIRM_DEFAULTS=yes only after reviewing the above."
  exit 1
fi

ADDR_FILE="$(cd "$(dirname "$0")" && pwd)/ewa-addresses.env"
touch "$ADDR_FILE"
# shellcheck disable=SC1090
source "$ADDR_FILE"
save_addr() { printf '%s=%s\n' "$1" "$2" >> "$ADDR_FILE"; echo "  saved: $1=$2"; }
eq_addr() { [ "$(printf '%s' "$1" | tr 'A-Z' 'a-z')" = "$(printf '%s' "$2" | tr 'A-Z' 'a-z')" ]; }

DEPLOYER="$(cast wallet address --private-key "$PK")"
echo "deployer: $DEPLOYER"
echo "rpc: $RPC"
echo ""

# ===== EVA_VerifyJury =====
echo "=== EVA_VerifyJury ==="
VERIFYJURY_
VERIFYJURY_ARGS=$(cast abi-encode "constructor(address,address,uint64,uint256,uint256,uint256,uint256,uint256)" $INCIDENTREG $EWA_CORE 259200 3 50 2000 500 1000000000000000000)
VERIFYJURY_ARGS=${VERIFYJURY_ARGS#0x}
VERIFYJURY=$(cast send --rpc-url $RPC --private-key $PK --create ${VERIFYJURY_BC}${VERIFYJURY_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${VERIFYJURY:-}" ]; then echo "FATAL: EVA_VerifyJury deploy failed"; exit 1; fi
echo "EVA_VerifyJury = $VERIFYJURY"
save_addr VERIFYJURY $VERIFYJURY
sleep 5
eq_addr "$(cast call $VERIFYJURY "REGISTRY()(address)" --rpc-url $RPC)" "$INCIDENTREG" || { echo "FATAL: VERIFYJURY registry mismatch"; exit 1; }
sleep 5

# ===== EVA_ThreatMarket =====
echo "=== EVA_ThreatMarket ==="
THREAT_
THREAT_ARGS=$(cast abi-encode "constructor(address,address,uint256)" $EWA_CORE $VERIFYJURY 20000)
THREAT_ARGS=${THREAT_ARGS#0x}
THREAT=$(cast send --rpc-url $RPC --private-key $PK --create ${THREAT_BC}${THREAT_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${THREAT:-}" ]; then echo "FATAL: EVA_ThreatMarket deploy failed"; exit 1; fi
echo "EVA_ThreatMarket = $THREAT"
save_addr THREAT $THREAT
sleep 5
eq_addr "$(cast call $THREAT "JURY()(address)" --rpc-url $RPC)" "$VERIFYJURY" || { echo "FATAL: THREAT jury mismatch"; exit 1; }
sleep 5

echo ""
echo "=================================================================="
echo "batch4-ewa complete — addresses this batch:"
echo "  VERIFYJURY=${VERIFYJURY:-MISSING}"
echo "  THREAT=${THREAT:-MISSING}"
echo "Full record: $ADDR_FILE"
echo "=================================================================="
